int ax25_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    int ret;
    struct sock *sk = sock->sk;

    lock_sock(sk);

    if (sk->sk_type == SOCK_SEQPACKET && sk->sk_state != TCP_ESTABLISHED) {
        release_sock(sk);
        return -ENOTCONN;
    }

    ret = sock_recvmsg(iocb, sock, msg, size, flags);
    if (ret < 0) {
        release_sock(sk);
        return ret;
    }

    if (msg->msg_name && msg->msg_namelen >= sizeof(struct sockaddr_ax25)) {
        struct sockaddr_ax25 *addr = (struct sockaddr_ax25 *)msg->msg_name;
        struct ax25_cb *ax25 = ax25_sk(sk);
        memcpy(addr->ax25_call.ax25_addr, ax25->source_call.ax25_addr, AX25_ADDR_LEN);
        addr->sa_family = AF_AX25;
        msg->msg_namelen = sizeof(struct sockaddr_ax25);
    }

    release_sock(sk);
    return ret;
}

