int ax25_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags)
{
    int ret;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;

    lock_sock(sk);

    if (sk->sk_type == SOCK_SEQPACKET && sk->sk_state != TCP_ESTABLISHED) {
        release_sock(sk);
        return -ENOTCONN;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        release_sock(sk);
        return -EAGAIN;
    }

    ret = skb->len;
    if (size < skb->len)
        ret = size;

    memcpy(msg->msg_name, &skb->cb.ax25_dst_addr, AX25_ADDR_LEN);
    msg->msg_namelen = AX25_ADDR_LEN;

    msg->msg_iter.iov = (struct iovec *)skb->data;
    msg->msg_iter.iov_len = 1;
    msg->msg_iter.count = ret;

    skb_pull(skb, ret);
    if (!skb->len)
        kfree_skb(skb);
    else
        skb_queue_head(&sk->sk_receive_queue, skb);

    release_sock(sk);
    return ret;
}

#include <linux/socket.h>
#include <linux/sockios.h>
#include <linux/uio.h>
#include <linux/net.h>
#include <net/sock.h>
#include <asm/atomic.h>

int ax25_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    lock_sock(sk);

    if (sock->type == SOCK_SEQPACKET && sk->sk_state != TCP_ESTABLISHED) {
        err = -ENOTCONN;
        goto out;
    }

    skb = skb_peek(&sk->sk_receive_queue);
    if (!skb) {
        err = -EAGAIN;
        goto out;
    }

    if (skb->len > size)
        skb = skb_unclone(skb, GFP_KERNEL);

    if (skb->len > size) {
        err = -EMSGSIZE;
        goto out;
    }

    skb_queue_walk(&sk->sk_receive_queue, skb) {
        copied += skb->len;
    }

    if (skb->data) {
        memcpy(msg->msg_name, skb->data, skb->len);
    }

    msg->msg_namelen = skb->len;
    msg->msg_flags = 0;

out:
    release_sock(sk);
    return copied ? copied : err;
}
